  this.solicitudes.pipe(tap(()=>{this.cargando.set(true);this.error.set('');this.resultado.set(null);}),switchMap(q=>{const key=JSON.stringify([q.vista,q.filtro]);const cached=this.cache.get(key);return (cached&&!q.refrescar&&Date.now()-cached.time<30000?of(cached.result):this.api.consultar(q.vista,q.filtro)).pipe(tap(result=>this.cache.set(key,{time:Date.now(),result})),map(result=>({result,error:''})),catchError(()=>of({result:null,error:'No pudimos cargar este análisis. Intenta actualizarlo.'})));}),takeUntilDestroyed(this.destroy)).subscribe(r=>{this.cargando.set(false);this.resultado.set(r.result);this.error.set(r.error);});
