 activarComparacion(){if(this.comparando||!this.permiteComparar)return;this.filtrosAbiertos=true;this.filtroGeneral={...this.filtro};this.comparando=true;this.verDetalle=false;this.filtro.escenario='todos';this.cargar(true);}
