 vista(){if(this.comparando&&this.area==='resumen')return 'comparacion';if(this.area==='ventas')return this.detalle; if(this.area==='inventario')return this.detalle==='compras'?'compras':'inventario';return 'resumen';}
 cargar(refrescar=false){this.cerrarExploracion();if(this.area==='predictivo'){if(this.puede('IA_PRONOSTICOS_VER'))this.cargarIa();return;}if(!this.puede('BI_VER'))return;if(this.area==='resumen'){this.filtro.categoria=undefined;this.filtro.elemento=undefined;this.filtro.cliente=undefined;this.filtro.proveedor=undefined;}if(!this.comparando)this.compararAnterior();this.filtro.comparar=this.comparando;this.solicitudes.next({vista:this.vista(),filtro:{...this.filtro},refrescar});}
 aplicar(){this.validarElemento();if(this.filtro.hasta<this.filtro.desde||this.comparando&&this.filtro.hastaB<this.filtro.desdeB){this.error.set('La fecha final debe ser igual o posterior al inicio.');return;}this.verDetalle=false;this.cargar(true);}
