 formato(v:unknown,key=''){if(v==null)return 'No calculable';if(['A','B','Diferencia','VentaNeta','Ticket','Importe','CompraNeta','PromedioCompra'].includes(key))return this.moneda(v);if(['Fecha','UltimaVenta','DiaEmision','Desde','Hasta'].includes(key))return this.fecha(String(v));if(['Variacion','Participacion','Conversion','TasaRecurrentes','PorcentajeSinStock','PorcentajeCritico'].includes(key))return this.numero(v).toLocaleString('es-PE',{maximumFractionDigits:2})+' %';return typeof v==='number'?v.toLocaleString('es-PE',{maximumFractionDigits:2}):String(v);}
