 get escenarios(){if(this.area==='ventas')return this.detalle==='clientes'?[{id:'clientes-caida',nombre:'Clientes recurrentes con reducción de compras'},{id:'cotizaciones-seguimiento',nombre:'Cotizaciones pendientes de seguimiento'}]:[{id:'productos-caida',nombre:'Productos con disminución de ventas'},{id:'categorias-caida',nombre:'Categorías con disminución de ventas'}];if(this.area==='inventario')return this.detalle==='compras'?[{id:'proveedor-concentrado',nombre:'Concentración de compras por proveedor'}]:[{id:'criticos-ventas',nombre:'Productos críticos con ventas recientes'},{id:'stock-inactivo',nombre:'Productos con stock y sin movimiento comercial'}];return [];}
