 get notasVista(){if(this.esCompras)return ['Compras registradas o confirmadas, sin IGV. No representan el costo de los productos vendidos ni la utilidad.','Cada compra se cuenta una vez. La participación usa el importe total filtrado; el detalle muestra hasta 100 proveedores.'];if(this.area==='inventario')return ['Stock actual de productos activos inventariables; los servicios se excluyen. Las fechas sólo delimitan las ventas usadas para revisar movimiento.','Stock crítico incluye productos sin stock. La cobertura histórica usa el ritmo observado, no una previsión de IA.'];const n=['Ventas confirmadas sin IGV. Una subida o caída de ventas no equivale a ganancia o pérdida.'];if(this.area==='resumen'||this.detalle==='clientes')n.push('Cotizaciones que terminaron en venta: venta confirmada vinculada dentro del plazo elegido, entre cotizaciones que ya completaron ese plazo. Sin base calculable, se omite el porcentaje.','Clientes que volvieron: compradores con una venta anterior al inicio del período.');if(this.area==='resumen')n.push('Stock crítico incluye sin stock; ambos porcentajes no se suman. Las existencias son actuales.');return n;}
