 get estadosStock():BiFila[]{const s=this.filas('stock')[0];if(!s||this.numero(s['Productos'])<=0)return [];return [{Nombre:'Sin stock',Registros:this.numero(s['SinStock'])},{Nombre:'Bajo mínimo con stock',Registros:Math.max(0,this.numero(s['Criticos'])-this.numero(s['SinStock']))},{Nombre:'Sobre el mínimo',Registros:Math.max(0,this.numero(s['Productos'])-this.numero(s['Criticos'])-this.numero(s['SaldoNoValido']))},{Nombre:'Saldo por revisar',Registros:this.numero(s['SaldoNoValido'])}].filter(r=>r.Registros>0);}
 evolucionMeses(key='evolucion'):BiFila[]{const out:BiFila[]=[];for(const id of this.comparando?['A','B']:['A']){const p=(key==='evolucionCompras'?this.filas('periodosCompras'):this.filas('periodos')).find(x=>x['Periodo']===id);if(!p?.['Desde']||!p['Hasta'])continue;const desde=String(p['Desde']).slice(0,10),hasta=String(p['Hasta']).slice(0,10);let month=desde.slice(0,7);let previo:number|null=null;while(month<=hasta.slice(0,7)){const inicio=month+'-01',d=new Date(inicio+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);const siguiente=d.toISOString().slice(0,10),fin=this.add(siguiente,-1);const parcial=desde>inicio||hasta<fin||(this.numero(p['DiaParcial'])===1&&month===hasta.slice(0,7));const original=this.filas(key).find(r=>r['Periodo']===id&&r['Nombre']===month);const importe=this.numero(original?.['Importe']);const Tono=parcial?'parcial':previo==null?'base':importe>previo?'sube':importe<previo?'baja':'igual';out.push({...original,Nombre:month,Periodo:id,Mes:this.mesAnio(month),Serie:this.comparando?'Período '+id:key==='evolucionCompras'?'Compras sin IGV':'Ventas sin IGV',Importe:importe,Tono,Parcial:parcial?1:0});previo=parcial?null:importe;month=siguiente.slice(0,7);}}return out;}
 resumenEvolucion(key='evolucion'){const r=this.evolucionMeses(key).filter(r=>r['Periodo']==='A');if(!r.length)return '';const sust=key==='evolucionCompras'?'compras':'ventas';if(r.length===1)return `${this.mesAnio(r[0]['Nombre'])}: ${this.moneda(r[0]['Importe'])} en ${sust}${r[0]['Parcial']?' del tramo consultado':''}. Un solo mes no permite afirmar una tendencia.`;const completos=r.filter(r=>!r['Parcial']);const last=completos.at(-1);if(!last)return 'Los meses mostrados están incompletos; compara tramos de igual duración.';const i=r.indexOf(last),prior=r[i-1];if(prior&&!prior['Parcial']&&this.numero(prior['Importe'])>0){const v=(this.numero(last['Importe'])/this.numero(prior['Importe'])-1)*100;return `${this.mesAnio(last['Nombre'])}: ${this.moneda(last['Importe'])}; ${v>=0?'subió':'bajó'} ${Math.abs(v).toLocaleString('es-PE',{maximumFractionDigits:1})} % frente al mes anterior completo.`;}return `${this.mesAnio(last['Nombre'])}: ${this.moneda(last['Importe'])} en ${sust}. Los tramos incompletos no se comparan como meses completos.`;}
 readonly columnas:Partial<Record<string,string>>={Nombre:'Nombre',A:'Ventas A sin IGV',B:'Ventas B sin IGV',Diferencia:'Cambio en S/',Variacion:'Cambio %',Cantidad:'Cantidad en A',Unidad:'Unidad',StockActual:'Stock actual',StockMinimo:'Mínimo',Vendido:'Vendido en A',CoberturaHistorica:'Cobertura al ritmo observado · días',Estado:'Estado',UltimaVenta:'Última venta',DiasSinVenta:'Días desde última venta',Importe:'Importe',Participacion:'Participación %',Operaciones:'Operaciones',OperacionesA:'Operaciones A',OperacionesB:'Operaciones B',Antiguedad:'Antigüedad · días',Fecha:'Fecha',Horizonte:'Días',CantidadMemoria:'Estimación',Real:'Venta observada',Wape:'Error relativo',EsSombra:'Experimental'};
 columnasTabla(key:string){if(key==='evolucionCompras')return this.comparando?['Nombre','Periodo','Importe']:['Nombre','Importe'];if(!this.comparando&&!this.necesitaReferencia){const general:Record<string,string[]>={evolucion:['Nombre','Importe'],productos:['Nombre','Unidad','A','Cantidad'],clientes:['Nombre','A','OperacionesA'],categorias:['Nombre','Importe']};if(general[key])return general[key];}return ({evolucion:['Nombre','Periodo','Importe'],categorias:['Nombre','Periodo','Importe'],productos:['Nombre','Unidad','A','B','Diferencia','Variacion'],clientes:['Nombre','A','B','Diferencia','Variacion','OperacionesA','OperacionesB'],cotizaciones:['Nombre','Fecha','Estado','Importe','Antiguedad'],inventario:['Nombre','Unidad','StockActual','StockMinimo','Vendido','CoberturaHistorica','UltimaVenta','Estado'],proveedores:['Nombre','Importe','Operaciones','Participacion']} as Record<string,string[]>)[key]??[];}
 cargarIa(){this.peticionIa?.unsubscribe();this.cargandoIa.set(true);this.errorIa.set('');this.peticionIa=this.api.predictivo().pipe(takeUntilDestroyed(this.destroy)).subscribe({next:r=>{this.pronostico.set(r);const disponibles=r.productos.filter(p=>p.sufficient&&p.daily.length>0);if(!disponibles.some(p=>p.id===this.productoIa))this.productoIa=disponibles[0]?.id??0;this.cargandoIa.set(false);},error:()=>{this.cargandoIa.set(false);this.errorIa.set('No pudimos cargar las estimaciones. El análisis histórico sigue disponible.');}});}
