  const ventas=this.area!=='inventario';
  if(ventas&&a){if(a['VentaNeta']!=null)add('ventas','Total vendido',this.moneda(a['VentaNeta']),`${a['Operaciones']} operaciones · sin IGV`,'Ventas','Valor de ventas confirmadas del período. El crecimiento exige una referencia positiva; no mide utilidad.');
   if(this.area==='ventas'&&this.detalle!=='clientes'){add('operaciones','Número de ventas',this.formato(a['Operaciones']),'Operaciones confirmadas','Ventas','Cada operación se cuenta una vez, aunque tenga varios productos.');if(a['Ticket']!=null)add('promedio','Venta promedio',this.moneda(a['Ticket']),'Sin IGV por operación','Ventas','Total vendido dividido entre el número de ventas.');}
   if(this.area==='resumen'||this.detalle==='clientes'){if(a['Conversion']!=null)add('conversion','Cotizaciones que terminaron en venta',this.formato(a['Conversion'],'Conversion'),`${a['Convertidas']} de ${a['Elegibles']} cotizaciones con plazo completo`,'Ventas',`Venta vinculada dentro de ${this.filtroAplicado.ventanaConversion} días. Se evalúan sólo plazos completos hasta ayer.`);if(a['TasaRecurrentes']!=null)add('recurrencia','Clientes que volvieron a comprar',this.formato(a['TasaRecurrentes'],'TasaRecurrentes'),`${a['Recurrentes']} de ${a['Compradores']} compradores`,'Ventas','Compradores con una venta confirmada anterior al inicio del período.');}
  }
