 get paginasGrupo(){const d=this.detallePagina();return d?Math.max(1,Math.ceil(d.totalRegistros/d.tamanioPagina)):1;}
 imagenDetalle(row:BiFila){const ruta=String(row['ImagenUrl']??'').trim();if(!ruta)return '';if(/^https?:\/\//i.test(ruta))return ruta;if(/^[a-z][a-z0-9+.-]*:/i.test(ruta)||ruta.startsWith('//'))return '';const base=environment.apiUrl.replace(/\/api\/?$/,'');return base+(ruta.startsWith('/')?'':'/')+ruta;}
 imagenFallida(row:BiFila){row['ImagenUrl']=null;this.detallePagina.update(d=>d?{...d,items:[...d.items]}:d);}
 iniciales(nombre:unknown){return String(nombre??'').trim().split(/\s+/).slice(0,2).map(p=>p[0]??'').join('').toUpperCase();}
 estadoProducto(row:BiFila){return row['Estado']==='Sin stock'?'agotado':row['Estado']==='Bajo mínimo con stock'?'bajo':row['Estado']==='Sobre el mínimo'?'disponible':'revisar';}
 puntosEvolucion(key='evolucion'):string[]{const rows=this.evolucionMeses(key).filter(r=>r['Periodo']==='A');if(!rows.length)return [];const puntos=[this.resumenEvolucion(key)];const completos=rows.filter(r=>!r['Parcial']);if(completos.length>1){const mayor=[...completos].sort((a,b)=>this.numero(b['Importe'])-this.numero(a['Importe']))[0];puntos.push(`Mayor importe en un mes completo: ${this.mesAnio(mayor['Nombre'])}, ${this.moneda(mayor['Importe'])} sin IGV.`);}const parcial=[...rows].reverse().find(r=>!!r['Parcial']);if(parcial&&rows.length>1)puntos.push(`${this.mesAnio(parcial['Nombre'])}: ${this.moneda(parcial['Importe'])} en el tramo consultado; todavía no es un mes completo.`);return puntos;}
 documentosExploracion=false;
 mesAnio(v:unknown){const s=String(v??'');if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(s))return s;const [y,m]=s.split('-').map(Number);const text=new Intl.DateTimeFormat('es-PE',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(y,m-1,1)));return text.charAt(0).toUpperCase()+text.slice(1);}
 cabecera(tabla:string,campo:string){if(campo==='Nombre')return ({cobertura:'Concepto',evolucion:'Mes',evolucionCompras:'Mes',estadoStock:'Disponibilidad',productos:'Producto o servicio',categorias:'Categoría',clientes:'Cliente',cotizaciones:'Cliente',inventario:'Producto',proveedores:'Proveedor'} as Record<string,string>)[tabla]??'Nombre';if(campo==='Periodo')return 'Período';if(campo==='Importe')return tabla==='cotizaciones'?'Importe · con IGV':'Importe · sin IGV';if(campo==='A')return this.comparando?'Ventas del período A · sin IGV':'Ventas · sin IGV';if(campo==='B')return this.comparando?'Ventas del período B · sin IGV':'Ventas de referencia · sin IGV';if(campo==='OperacionesA')return this.comparando?'Ventas en A':'Número de ventas';if(campo==='Cantidad')return ['saldo','cobertura'].includes(tabla)?'Cantidad':tabla==='predictivo'?'Cantidad por día':'Cantidad vendida';if(campo==='Serie')return 'Dato';if(campo==='Emitidas')return 'Cotizaciones emitidas';if(campo==='Elegibles')return 'Con plazo completo';if(campo==='Convertidas')return 'Terminaron en venta';if(campo==='Conversion')return 'Cotizaciones que terminaron en venta';if(campo==='Registros')return 'Cantidad de registros';if(campo==='Compradores')return 'Compradores';if(campo==='Recurrentes')return 'Con compra anterior';if(campo==='TasaRecurrentes')return 'Compradores recurrentes %';if(campo==='CompraNeta')return 'Total comprado · sin IGV';if(campo==='Compras')return 'Número de compras';if(campo==='VentaNeta')return 'Total vendido · sin IGV';if(campo==='Desde')return 'Desde';if(campo==='Hasta')return 'Hasta';return this.columnas[campo]??campo;}
 celda(tabla:string,campo:string,fila:BiFila){if(['evolucion','evolucionCompras'].includes(tabla)&&campo==='Nombre')return this.mesAnio(fila[campo]);if(campo==='Periodo')return fila[campo]==='A'?'Seleccionado (A)':fila[campo]==='B'?'Referencia (B)':String(fila[campo]);return this.formato(fila[campo],campo);}
